privateKey.description:
The private key for used by the crypto module to create signed tokens or encrypt data.
@default ""
@environment `AFFINE_PRIVATE_KEY`

SMTP.name.description:
Hostname used for SMTP HELO/EHLO (e.g. mail.example.com). Leave empty to use the system hostname.
@default ""
@environment `MAILER_SERVERNAME`

SMTP.host.description:
Host of the email server (e.g. smtp.gmail.com)
@default ""
@environment `MAILER_HOST`

SMTP.port.description:
Port of the email server (they commonly are 25, 465 or 587)
@default 465
@environment `MAILER_PORT`

SMTP.username.description:
Username used to authenticate the email server
@default ""
@environment `MAILER_USER`

SMTP.password.description:
Password used to authenticate the email server
@default ""
@environment `MAILER_PASSWORD`

SMTP.sender.description:
Sender of all the emails (e.g. "AFFiNE Self Hosted &lt;noreply@example.com&gt;")
@default "AFFiNE Self Hosted <noreply@example.com>"
@environment `MAILER_SENDER`

SMTP.ignoreTLS.description:
Whether ignore email server's TLS certificate verification. Enable it for self-signed certificates.
@default false
@environment `MAILER_IGNORE_TLS`

transports.description:
The enabled transports for accepting websocket traffics.
@default ["websocket","polling"]
@link https://docs.nestjs.com/websockets/gateways#transports

externalUrl.description:
Base url of AFFiNE server, used for generating external urls.
Default to be `[server.protocol]://[server.host][:server.port]` if not specified.

@default ""
@environment `AFFINE_SERVER_EXTERNAL_URL`

https.description:
Whether the server is hosted on a ssl enabled domain (https://).
@default false
@environment `AFFINE_SERVER_HTTPS`

listenAddr.description:
The address to listen on (e.g., 0.0.0.0 for IPv4, :: for IPv6).
@default "0.0.0.0"
@environment `LISTEN_ADDR`

port.description:
Which port the server will listen on.
@default 3010
@environment `AFFINE_SERVER_PORT`

path.description:
Subpath where the server get deployed if there is one.(e.g. /affine)
@default ""
@environment `AFFINE_SERVER_SUB_PATH`

ga4.measurementId.description:
GA4 Measurement ID for Measurement Protocol.
@default ""
@environment `GA4_MEASUREMENT_ID`

ga4.apiSecret.description:
GA4 API secret for Measurement Protocol.
@default ""
@environment `GA4_API_SECRET`

provider.apiKey.description:
Indexer search service api key. Optional for remote providers
@default ""
@link https://www.elastic.co/guide/server/current/api-key.html

provider.username.description:
Indexer search service auth username, if not set, basic auth will be disabled. Optional for remote providers
@default ""
@link https://www.elastic.co/guide/en/elasticsearch/reference/current/http-clients.html

providers.oidc.description:
OIDC OAuth provider config. Private network access requires allowPrivateNetwork: true
@default {"clientId":"","clientSecret":"","issuer":"","allowPrivateNetwork":false,"args":{}}
@link https://openid.net/specs/openid-connect-core-1_0.html

stripe.description:
Stripe sdk options and credentials
@default {"apiKey":"","webhookKey":""}
@link https://docs.stripe.com/api
